borders/border-color:
.box {
  padding: 24px;
  background: #e6ecff;
  border-style: solid;
  border-width: 6px;
  border-color: royalblue;
}

borders/no-border:
.btn {
  padding: 10px 22px;
  font-size: 16px;
  background: #2d56f2;
  color: white;
  border: none;
}

borders/styles:
.demo {
  padding: 12px;
  margin-bottom: 12px;
  border-width: 4px;
  border-color: #2d56f2;
}

/* Har bir qutiga oʻz border-style qiymatini bering */
.dashed {
  border-style: dashed;
}

.dotted {
  border-style: dotted;
}

.double {
  border-style: double;
}

borders/circles:
.avatar {
  width: 120px;
  height: 120px;
  display: grid;
  place-items: center;
  background: #2d56f2;
  color: white;
  font-size: 36px;
  font-weight: bold;
  border-radius: 50%;
}

.pill {
  margin-top: 16px;
  padding: 10px 28px;
  font-size: 16px;
  background: white;
  color: #2d56f2;
  border: 2px solid #2d56f2;
  border-radius: 999px;
}

borders/corners:
.bubble {
  display: inline-block;
  max-width: 260px;
  padding: 14px 18px;
  background: #2d56f2;
  color: white;
  border-radius: 20px 20px 20px 0;
}

borders/outline:
.item {
  width: 200px;
  padding: 12px;
  margin-bottom: 14px;
  background: #e6ecff;
}

.selected {
  outline: 3px solid orange;
  outline-offset: 4px;
}

borders/box-sizing:
.box {
  width: 200px;
  padding: 20px;
  border: 10px solid #2d56f2;
  background: #e6ecff;
  box-sizing: border-box;
}

borders/tables:
.planets {
  border-collapse: collapse;
}

.planets th,
.planets td {
  border: 1px solid #56617a;
  padding: 8px 18px;
}

.planets th {
  border-bottom: 3px solid #56617a;
}

borders/challenge:
.profile {
  width: 280px;
  padding: 20px;
  background: white;
  border: 2px solid royalblue;
  border-radius: 16px;
  box-sizing: border-box;
}

.avatar {
  width: 80px;
  height: 80px;
  display: grid;
  place-items: center;
  background: #2d56f2;
  color: white;
  font-size: 28px;
  font-weight: bold;
  border: 4px solid gold;
  border-radius: 50%;
}

.profile h2 {
  margin: 12px 0 0;
}

.role {
  margin: 0 0 12px;
  color: #56617a;
}

.row {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px dashed gray;
}

.follow {
  margin-top: 16px;
  padding: 10px 26px;
  font-size: 16px;
  background: #2d56f2;
  color: white;
  border: none;
  border-radius: 999px;
}

margins/margin-sides:
.box {
  padding: 12px;
  background: #e6ecff;
  border: 2px solid #2d56f2;
  margin-left: 40px;
  margin-top: 16px;
}

margins/margin-two:
.badge {
  display: inline-block;
  padding: 4px 12px;
  background: #2d56f2;
  color: white;
  border-radius: 999px;
  margin: 8px 24px;
}

margins/margin-four:
.box {
  padding: 12px;
  background: #e6ecff;
  border: 2px solid #2d56f2;
}

.one {
  margin: 10px 20px 30px 40px;
}

.two {
  margin: 5px 15px 25px;
}

margins/margin-auto:
.box {
  width: 240px;
  padding: 12px;
  background: #e6ecff;
  border: 2px solid #2d56f2;
  margin: 0 auto;
}

margins/margin-push:
.logout {
  width: 120px;
  padding: 10px;
  text-align: center;
  background: #fde5e7;
  border: 2px solid #c1303c;
  margin-left: auto;
}

margins/margin-negative:
.card {
  padding: 20px;
  background: white;
  border: 2px solid #2d56f2;
}

.banner {
  padding: 10px 20px;
  background: #2d56f2;
  color: white;
  font-weight: bold;
  margin: 0 -20px;
}

margins/collapse-siblings:
.box {
  padding: 12px;
  background: #e6ecff;
  border: 2px solid #2d56f2;
}

.a {
  margin-bottom: 30px;
}

.b {
  margin-top: 50px;
}

margins/collapse-parent:
.outer {
  background: #fff3c4;
  display: flow-root;
}

.inner {
  margin-top: 30px;
  padding: 12px;
  background: #e6ecff;
  border: 2px solid #2d56f2;
}

margins/margins-add:
.row {
  display: flex;
}

.box {
  padding: 12px;
  background: #e6ecff;
  border: 2px solid #2d56f2;
}

.a {
  margin-right: 10px;
}

.b {
  margin-left: 30px;
}

margins/inline-margin:
.tag {
  padding: 2px 10px;
  background: #2d56f2;
  color: white;
  margin-top: 12px;
  display: inline-block;
}

margins/margin-units:
.note {
  font-size: 20px;
  padding: 12px;
  background: #fff3c4;
  border: 2px solid #d9a400;
  margin-bottom: 1.5em;
  margin-left: 10%;
}

margins/last-child:
.menu {
  margin: 0;
  padding: 0;
  list-style: none;
}

.menu li {
  margin-bottom: 12px;
  padding: 8px 12px;
  background: #e6ecff;
}

.menu li:last-child {
  margin-bottom: 0;
}

margins/margin-challenge:
.post {
  width: 300px;
  padding: 20px;
  background: white;
  border: 2px solid #2d56f2;
  margin: 24px auto;
}

.banner {
  padding: 10px 20px;
  background: #2d56f2;
  color: white;
  font-weight: bold;
  margin: 0 -20px 16px;
}

.post h2 {
  margin: 0 0 8px;
}

.post p {
  margin: 0 0 12px;
}

.tag {
  padding: 2px 10px;
  background: #e6ecff;
  border-radius: 999px;
  margin-right: 8px;
}

.more {
  padding: 8px 20px;
  font-size: 15px;
  display: block;
  margin-left: auto;
}
